[patterns/itsm-operations/api-microservices/PTN-OPS-API-002-health-check-pattern.md#phase-1-aspnet-core-health-check-implementation]

#### Phase 1: ASP.NET Core Health Check Implementation

**Step 1: Install NuGet Packages**

```powershell
# Core health check package
dotnet add package Microsoft.Extensions.Diagnostics.HealthChecks --version 8.0.0

# Database health check
dotnet add package AspNetCore.HealthChecks.SqlServer --version 8.0.0

# Redis health check
dotnet add package AspNetCore.HealthChecks.Redis --version 8.0.0

# URL health check (for downstream services)
dotnet add package AspNetCore.HealthChecks.Uris --version 8.0.0

# Health check UI (detailed JSON response)
dotnet add package AspNetCore.HealthChecks.UI.Client --version 8.0.0
```

**Step 2: Configure Health Checks in Startup.cs**

```csharp
using Microsoft.AspNetCore.Diagnostics.HealthChecks;
using Microsoft.Extensions.Diagnostics.HealthChecks;
using HealthChecks.UI.Client;

public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Register health checks with dependency validation
        services.AddHealthChecks()
            // Database health check (critical dependency)
            .AddSqlServer(
                connectionString: Configuration.GetConnectionString("ClaimsDB"),
                healthQuery: "SELECT 1",
                name: "claims-database",
                failureStatus: HealthStatus.Unhealthy,
                tags: new[] { "ready", "database", "critical" },
                timeout: TimeSpan.FromSeconds(2))

            // Redis cache health check (optional dependency)
            .AddRedis(
                redisConnectionString: Configuration.GetConnectionString("Redis"),
                name: "redis-cache",
                failureStatus: HealthStatus.Degraded,  // Cache failure = degraded
                tags: new[] { "ready", "cache", "optional" },
                timeout: TimeSpan.FromSeconds(2))

            // Downstream service health check
            .AddUrlGroup(
                uri: new Uri("http://eligibility-service:8080/health/ready"),
                name: "eligibility-service",
                failureStatus: HealthStatus.Degraded,
                tags: new[] { "ready", "downstream" },
                timeout: TimeSpan.FromSeconds(2),
                configurePrimaryHttpMessageHandler: () => new SocketsHttpHandler
                {
                    PooledConnectionLifetime = TimeSpan.FromMinutes(2),
                    MaxConnectionsPerServer = 5
                })

            // Custom initialization check
            .AddCheck<CacheInitializationHealthCheck>(
                name: "cache-initialization",
                failureStatus: HealthStatus.Unhealthy,
                tags: new[] { "ready", "initialization" });
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        // Liveness probe - minimal check
        app.UseHealthChecks("/health/live", new HealthCheckOptions
        {
            Predicate = _ => false,  // No dependency checks
            AllowCachingResponses = false,
            ResponseWriter = async (context, report) =>
            {
                context.Response.ContentType = "application/json";
                var response = new
                {
                    status = "healthy",
                    service = Configuration["ServiceName"],
                    version = Configuration["Version"],
                    timestamp = DateTime.UtcNow
                };
                await context.Response.WriteAsync(
                    JsonSerializer.Serialize(response, new JsonSerializerOptions
                    {
                        WriteIndented = true
                    }));
            }
        });

        // Readiness probe - comprehensive checks
        app.UseHealthChecks("/health/ready", new HealthCheckOptions
        {
            Predicate = check => check.Tags.Contains("ready"),
            AllowCachingResponses = false,
            ResponseWriter = UIResponseWriter.WriteHealthCheckUIResponse,
            ResultStatusCodes =
            {
                [HealthStatus.Healthy] = StatusCodes.Status200OK,
                [HealthStatus.Degraded] = StatusCodes.Status200OK,
                [HealthStatus.Unhealthy] = StatusCodes.Status503ServiceUnavailable
            }
        });

        // Startup probe - same as liveness
        app.UseHealthChecks("/health/startup", new HealthCheckOptions
        {
            Predicate = _ => false,
            AllowCachingResponses = false,
            ResponseWriter = async (context, report) =>
            {
                context.Response.ContentType = "application/json";
                await context.Response.WriteAsync(
                    JsonSerializer.Serialize(new { status = "healthy" }));
            }
        });
    }
}
```

**Step 3: Implement Custom Health Check**

```csharp
public class CacheInitializationHealthCheck : IHealthCheck
{
    private readonly ICacheService _cacheService;
    private readonly ILogger<CacheInitializationHealthCheck> _logger;

    public CacheInitializationHealthCheck(
        ICacheService cacheService,
        ILogger<CacheInitializationHealthCheck> logger)
    {
        _cacheService = cacheService;
        _logger = logger;
    }

    public Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context,
        CancellationToken cancellationToken = default)
    {
        try
        {
            if (!_cacheService.IsInitialized)
            {
                _logger.LogWarning(
                    "Cache initialization incomplete: {Progress}% complete",
                    _cacheService.InitializationProgress);

                return Task.FromResult(HealthCheckResult.Unhealthy(
                    "Cache initialization not complete",
                    data: new Dictionary<string, object>
                    {
                        { "progress", $"{_cacheService.InitializationProgress}%" },
                        { "estimatedTimeRemaining", _cacheService.EstimatedTimeRemaining },
                        { "recordsLoaded", _cacheService.RecordCount },
                        { "targetRecords", _cacheService.TotalRecords }
                    }));
            }

            // Validate cache functionality
            var testKey = "__health_check_test__";
            _cacheService.Set(testKey, "test", TimeSpan.FromSeconds(10));
            var testValue = _cacheService.Get<string>(testKey);

            if (testValue != "test")
            {
                return Task.FromResult(HealthCheckResult.Degraded(
                    "Cache initialized but validation failed"));
            }

            return Task.FromResult(HealthCheckResult.Healthy(
                "Cache fully initialized and functional",
                data: new Dictionary<string, object>
                {
                    { "recordsLoaded", _cacheService.RecordCount },
                    { "hitRate", $"{_cacheService.HitRate:P2}" },
                    { "memoryUsage", $"{_cacheService.MemoryUsageMB} MB" }
                }));
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Cache health check failed");
            return Task.FromResult(HealthCheckResult.Unhealthy(
                "Cache health check exception",
                exception: ex));
        }
    }
}
```

**Step 4: Configure Kubernetes Deployment**

```yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: claims-service
  namespace: claims
spec:
  replicas: 10
  selector:
    matchLabels:
      app: claims-service
  template:
    metadata:
      labels:
        app: claims-service
        version: v1
    spec:
      containers:
      - name: claims-service
        image: gainwell/claims-service:v1.0
        ports:
        - containerPort: 8080
          name: http
          protocol: TCP

        # Startup probe - allow 5 minutes for initialization
        startupProbe:
          httpGet:
            path: /health/startup
            port: 8080
            scheme: HTTP
          initialDelaySeconds: 0
          periodSeconds: 10
          timeoutSeconds: 5
          successThreshold: 1
          failureThreshold: 30  # 30 * 10s = 5 minutes

        # Liveness probe - detect unrecoverable failures
        livenessProbe:
          httpGet:
            path: /health/live
            port: 8080
            scheme: HTTP
          initialDelaySeconds: 60  # After startup probe succeeds
          periodSeconds: 10
          timeoutSeconds: 5
          successThreshold: 1
          failureThreshold: 3  # 3 * 10s = 30 seconds to detect

        # Readiness probe - control traffic routing
        readinessProbe:
          httpGet:
            path: /health/ready
            port: 8080
            scheme: HTTP
          initialDelaySeconds: 10
          periodSeconds: 5
          timeoutSeconds: 3
          successThreshold: 1
          failureThreshold: 2  # 2 * 5s = 10 seconds to remove from LB

        resources:
          requests:
            memory: "512Mi"
            cpu: "500m"
          limits:
            memory: "1Gi"
            cpu: "1000m"

        env:
        - name: ASPNETCORE_ENVIRONMENT
          value: "Production"
        - name: ConnectionStrings__ClaimsDB
          valueFrom:
            secretKeyRef:
              name: claims-db-secret
              key: connectionString
```

