**Step 3: Implement Custom Health Indicator**

```java
import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.stereotype.Component;

@Component("cacheInitialization")
public class CacheInitializationHealthIndicator implements HealthIndicator {

    private final CacheService cacheService;

    public CacheInitializationHealthIndicator(CacheService cacheService) {
        this.cacheService = cacheService;
    }

    @Override
    public Health health() {
        try {
            if (!cacheService.isInitialized()) {
                return Health.down()
                    .withDetail("status", "initializing")
                    .withDetail("progress", cacheService.getInitializationProgress() + "%")
                    .withDetail("recordsLoaded", cacheService.getRecordCount())
                    .withDetail("targetRecords", cacheService.getTotalRecords())
                    .build();
            }

            // Test cache functionality
            String testKey = "__health_check_test__";
            cacheService.set(testKey, "test");
            String testValue = cacheService.get(testKey);

            if (!"test".equals(testValue)) {
                return Health.down()
                    .withDetail("status", "validation-failed")
                    .build();
            }

            return Health.up()
                .withDetail("status", "operational")
                .withDetail("recordsLoaded", cacheService.getRecordCount())
                .withDetail("hitRate", String.format("%.2f%%", cacheService.getHitRate() * 100))
                .withDetail("memoryUsageMB", cacheService.getMemoryUsageMB())
                .build();

        } catch (Exception ex) {
            return Health.down()
                .withException(ex)
                .withDetail("error", ex.getMessage())
                .build();
        }
    }
}
