**Step 2: Implement Health Check Middleware**

```javascript
// healthCheck.js
const redis = require('ioredis');
const sql = require('tedious');

class HealthCheckService {
    constructor(config) {
        this.config = config;
        this.redisClient = new redis(config.redis);
        this.cacheInitialized = false;
    }

    // Liveness check - minimal
    async checkLiveness() {
        return {
            status: 'healthy',
            service: this.config.serviceName,
            timestamp: new Date().toISOString()
        };
    }

    // Readiness check - comprehensive
    async checkReadiness() {
        const checks = {
            database: await this.checkDatabase(),
            redis: await this.checkRedis(),
            initialization: await this.checkInitialization()
        };

        const allHealthy = Object.values(checks).every(c => c.status === 'healthy');
        const anyUnhealthy = Object.values(checks).some(c => c.status === 'unhealthy');

        return {
            status: anyUnhealthy ? 'unhealthy' : (allHealthy ? 'healthy' : 'degraded'),
            checks,
            timestamp: new Date().toISOString()
        };
    }

    async checkDatabase() {
        try {
            const connection = new sql.Connection(this.config.database);

            return new Promise((resolve) => {
                const timeout = setTimeout(() => {
                    resolve({ status: 'unhealthy', error: 'timeout' });
                }, 2000);

                connection.on('connect', (err) => {
                    clearTimeout(timeout);
                    if (err) {
                        resolve({
                            status: 'unhealthy',
                            error: err.message
                        });
                    } else {
                        connection.close();
                        resolve({
                            status: 'healthy',
                            responseTime: '15ms'
                        });
                    }
                });

                connection.connect();
            });
        } catch (error) {
            return { status: 'unhealthy', error: error.message };
        }
    }

    async checkRedis() {
        try {
            const start = Date.now();
            await this.redisClient.ping();
            const responseTime = Date.now() - start;

            return {
                status: 'healthy',
                responseTime: `${responseTime}ms`
            };
        } catch (error) {
            return {
                status: 'degraded',  // Redis optional
                error: error.message
            };
        }
    }

    async checkInitialization() {
        if (!this.cacheInitialized) {
            return {
                status: 'unhealthy',
                message: 'Cache initialization incomplete'
            };
        }
        return {
            status: 'healthy',
            message: 'Service fully initialized'
        };
    }
}

module.exports = HealthCheckService;
```

**Step 3: Configure Express Routes**

```javascript
// app.js
const express = require('express');
const HealthCheckService = require('./healthCheck');

const app = express();
const healthCheck = new HealthCheckService({
    serviceName: 'claims-service',
    database: {
        server: process.env.DB_SERVER,
        authentication: {
            type: 'default',
            options: {
                userName: process.env.DB_USERNAME,
                password: process.env.DB_PASSWORD
            }
        }
    },
    redis: {
        host: process.env.REDIS_HOST,
        port: process.env.REDIS_PORT
    }
});

// Liveness probe
app.get('/health/live', async (req, res) => {
    const result = await healthCheck.checkLiveness();
    res.status(200).json(result);
});

// Readiness probe
app.get('/health/ready', async (req, res) => {
    const result = await healthCheck.checkReadiness();
    const statusCode = result.status === 'unhealthy' ? 503 : 200;
    res.status(statusCode).json(result);
});

// Startup probe
app.get('/health/startup', async (req, res) => {
    const result = await healthCheck.checkLiveness();
    res.status(200).json(result);
});

app.listen(8080, () => {
    console.log('Claims Service listening on port 8080');
});
